// One row per client service you are paid to keep running.
// Add a line here the day a client goes live - not the day it first breaks.
return [
  { json: { client: 'Demo Clinic', url: (process.env.CHATBOT_URL || 'http://chatbot:3000') + '/api/health' } },
  { json: { client: 'Document AI', url: (process.env.DOCAI_URL || 'http://document-ai:3100') + '/api/health' } }
];

// Mark each service up or down. neverError + continueRegularOutput above mean
// a dead service arrives here as data rather than killing the whole run -
// otherwise the first outage stops you checking the rest.
const out = [];

for (const [i, item] of $input.all().entries()) {
  const target = $('Services to Check').all()[i]?.json || {};
  const status = item.json.statusCode || 0;
  const healthy = status >= 200 && status < 300 && item.json.body?.status === 'ok';

  out.push({
    json: {
      client: target.client,
      url: target.url,
      healthy,
      status,
      detail: healthy ? 'ok' : (item.json.error?.message || `HTTP ${status || 'no response'}`),
      checkedAt: new Date().toISOString()
    }
  });
}

return out;

